CREATE FUNCTION public.can_use_social_hub(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role IN ('super_admin','manager','receptionist')) AND NOT EXISTS(SELECT 1 FROM public.staff WHERE user_id=_user_id AND status IN ('suspended','disabled','pending')); $$;
REVOKE ALL ON FUNCTION public.can_use_social_hub(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.can_use_social_hub(uuid) TO authenticated, service_role;
CREATE TABLE public.social_conversations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), platform text NOT NULL, account_id text NOT NULL, external_thread_id text NOT NULL, kind text NOT NULL, participant_id text, participant_name text NOT NULL DEFAULT 'Unknown sender', status text NOT NULL DEFAULT 'open', last_event_at timestamptz NOT NULL DEFAULT now(), last_inbound_at timestamptz, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(platform,account_id,external_thread_id));
GRANT SELECT ON public.social_conversations TO authenticated; GRANT ALL ON public.social_conversations TO service_role;
ALTER TABLE public.social_conversations ENABLE ROW LEVEL SECURITY;
CREATE POLICY social_conversations_read ON public.social_conversations FOR SELECT TO authenticated USING(public.can_use_social_hub(auth.uid()));
CREATE TRIGGER social_conversations_updated BEFORE UPDATE ON public.social_conversations FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
CREATE INDEX social_conversations_recent ON public.social_conversations(last_event_at DESC);
CREATE TABLE public.social_messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), conversation_id uuid NOT NULL REFERENCES public.social_conversations(id) ON DELETE CASCADE, platform text NOT NULL, external_id text NOT NULL, sender_id text, sender_name text, direction text NOT NULL, kind text NOT NULL, body text NOT NULL DEFAULT '', attachments jsonb NOT NULL DEFAULT '[]', parent_id text, is_deleted boolean NOT NULL DEFAULT false, sent_by uuid, occurred_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(platform,external_id));
GRANT SELECT ON public.social_messages TO authenticated; GRANT ALL ON public.social_messages TO service_role;
ALTER TABLE public.social_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY social_messages_read ON public.social_messages FOR SELECT TO authenticated USING(public.can_use_social_hub(auth.uid()));
CREATE TRIGGER social_messages_updated BEFORE UPDATE ON public.social_messages FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
CREATE INDEX social_messages_thread ON public.social_messages(conversation_id,occurred_at);
CREATE TABLE public.social_activity(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), platform text, action text NOT NULL, conversation_id uuid REFERENCES public.social_conversations(id), actor_id uuid, event_key text UNIQUE, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.social_activity TO authenticated; GRANT ALL ON public.social_activity TO service_role;
ALTER TABLE public.social_activity ENABLE ROW LEVEL SECURITY;
CREATE POLICY social_activity_read ON public.social_activity FOR SELECT TO authenticated USING(public.can_use_social_hub(auth.uid()));
CREATE INDEX social_activity_recent ON public.social_activity(created_at DESC);
INSERT INTO public.social_activity(platform,action,actor_id,event_key,details,created_at) SELECT NULL,action,user_id,'legacy:'||id::text,'{}'::jsonb,created_at FROM public.activity_logs WHERE action ILIKE '%social%' OR action ILIKE '%instagram%';
CREATE TABLE public.social_delivery_state(platform text PRIMARY KEY, verified_at timestamptz, subscribed_at timestamptz, last_received_at timestamptz, last_error text, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.social_delivery_state TO authenticated; GRANT ALL ON public.social_delivery_state TO service_role;
ALTER TABLE public.social_delivery_state ENABLE ROW LEVEL SECURITY;
CREATE POLICY social_delivery_read ON public.social_delivery_state FOR SELECT TO authenticated USING(public.can_use_social_hub(auth.uid()));
CREATE TRIGGER social_delivery_updated BEFORE UPDATE ON public.social_delivery_state FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
ALTER PUBLICATION supabase_realtime ADD TABLE public.social_conversations, public.social_messages, public.social_activity;